import configparser

def _t():
    parser = configparser.ConfigParser()
    import decimal
    parser.converters['decimal'] = decimal.Decimal
    parser.read_string('\n            [s1]\n            one = 1\n            [s2]\n            two = 2\n        ')
    assert 'decimal' in parser.converters, ('assertIn', 'decimal', parser.converters)
    assert parser.getdecimal('s1', 'one') == 1, ('assertEqual', parser.getdecimal('s1', 'one'), 1)
    assert parser.getdecimal('s2', 'two') == 2, ('assertEqual', parser.getdecimal('s2', 'two'), 2)
    assert parser['s1'].getdecimal('one') == 1, ('assertEqual', parser['s1'].getdecimal('one'), 1)
    assert parser['s2'].getdecimal('two') == 2, ('assertEqual', parser['s2'].getdecimal('two'), 2)
    del parser.getdecimal
    try:
        parser.getdecimal('s1', 'one')
    except AttributeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    assert 'decimal' in parser.converters, ('assertIn', 'decimal', parser.converters)
    del parser.converters['decimal']
    assert 'decimal' not in parser.converters, ('assertNotIn', 'decimal', parser.converters)
    try:
        parser.getdecimal('s1', 'one')
    except AttributeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        parser['s1'].getdecimal('one')
    except AttributeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        parser['s2'].getdecimal('two')
    except AttributeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
